create or replace function public.profplus_admin_stats() returns jsonb language sql security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('activeAccounts',(select count(*) from (select user_id from public.conversations union select user_id from public.documents union select user_id from public.projects) a),'conversations',(select count(*) from public.conversations where deleted=0),'projects',(select count(*) from public.projects),'documents',(select count(*) from public.documents),'readyDocuments',(select count(*) from public.documents where status='ready'),'failedDocuments',(select count(*) from public.documents where status='failed'),'libraryMaterials',(select count(*) from public.library_materials),'libraryIndexed',(select count(*) from public.library_import_documents where state->>'status'='indexed' and state->>'attached'='1' and nullif(state->>'file_id','') is not null),'newsPublished',(select count(*) from public.profplus_news where status='published'),'newsDrafts',(select count(*) from public.profplus_news where status='draft'),'recentEdits',(select coalesce(jsonb_agg(t),'[]'::jsonb) from (select action,object_id,created_at from public.profplus_admin_audit where created_at>=now()-interval '90 days' order by created_at desc limit 20)t));
$$;
notify pgrst,'reload schema';
